41	std::tuple<const aclTensor *, const aclTensor *> FusedInferAttentionScore(
42	    const aclTensor *query,
43	    const aclTensorList *key,
44	    const aclTensorList *value,
45	    const aclTensor *pseShiftOptional,
46	    const aclTensor *attenMaskOptional,
47	    const aclIntArray *actualSeqLengthsOptional,
48	    const aclIntArray *actualSeqLengthsKvOptional,
49	    const aclTensor *deqScale1Optional,
50	    const aclTensor *quantScale1Optional,
51	    const aclTensor *deqScale2Optional,
52	    const aclTensor *quantScale2Optional,
53	    const aclTensor *quantOffset2Optional,
54	    const aclTensor *antiquantScaleOptional,
55	    const aclTensor *antiquantOffsetOptional,
