65	    const aclIntArray *actualSharedPrefixLenOptional,
66	    const aclTensor *queryRopeOptional,
67	    const aclTensor *keyRopeOptional,
68	    const aclTensor *keyRopeAntiquantScaleOptional,
69	    const aclTensor *dequantScaleQueryOptional,
70	    const aclTensor *learnableSinkOptional,
71	    const aclIntArray *qStartIdxOptional,
72	    const aclIntArray *kvStartIdxOptional,
73	    int64_t numHeads,
74	    double scaleValue,
75	    int64_t preTokens,
76	    int64_t nextTokens,
77	    const char *inputLayout,
78	    int64_t numKeyValueHeads,
79	    int64_t sparseMode,
80	    int64_t innerPrecise,
81	    int64_t blockSize,
