87	    int64_t pseType,
88	    int64_t outDtype,
89	    const aclTensor *attentionOut,
90	    const aclTensor *softmaxLse,
91	    aclOpExecutor *executor)
92	{
93	    L0_DFX(FusedInferAttentionScore, query, key, value, pseShiftOptional, attenMaskOptional,
94	           actualSeqLengthsOptional, actualSeqLengthsKvOptional, deqScale1Optional, quantScale1Optional,
95	           deqScale2Optional, quantScale2Optional, quantOffset2Optional, antiquantScaleOptional,
96	           antiquantOffsetOptional, blockTableOptional, queryPaddingSizeOptional, kvPaddingSizeOptional,
97	           keyAntiquantScaleOptional, keyAntiquantOffsetOptional, valueAntiquantScaleOptional,
98	           valueAntiquantOffsetOptional, keySharedPrefixOptional, valueSharedPrefixOptional,
99	           actualSharedPrefixLenOptional, queryRopeOptional, keyRopeOptional, keyRopeAntiquantScaleOptional,
100	           dequantScaleQueryOptional, learnableSinkOptional, qStartIdxOptional, kvStartIdxOptional,
101	           numHeads, scaleValue, preTokens, nextTokens, inputLayout, numKeyValueHeads, sparseMode, innerPrecise,
102	           blockSize, antiquantMode, softmaxLseFlag, keyAntiquantMode, valueAntiquantMode, queryQuantMode, pseType,
103	           outDtype);
104	
105	    if (executor == nullptr) {
106	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "FusedInferAttentionScore: executor is nullptr.");
107	        return {nullptr, nullptr};
108	    }
109	    if (attentionOut == nullptr) {
110	        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "FusedInferAttentionScore: attentionOut is nullptr.");
111	        return {nullptr, nullptr};
112	    }
113	    if (softmaxLse == nullptr) {
114	        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "FusedInferAttentionScore: softmaxLse is nullptr.");
115	        return {nullptr, nullptr};
116	    }
117	
118	    const aclTensor *actualSeqLengthsTensor = ConvertIntArrayToTensor(actualSeqLengthsOptional, executor);
119	    const aclTensor *actualSeqLengthsKvTensor = ConvertIntArrayToTensor(actualSeqLengthsKvOptional, executor);
120	    const aclTensor *actualSharedPrefixLenTensor = ConvertIntArrayToTensor(actualSharedPrefixLenOptional, executor);
121	    const aclTensor *qStartIdxTensor = ConvertIntArrayToTensor(qStartIdxOptional, executor);
122	    const aclTensor *kvStartIdxTensor = ConvertIntArrayToTensor(kvStartIdxOptional, executor);
123	    if ((actualSeqLengthsOptional != nullptr && actualSeqLengthsTensor == nullptr) ||
124	        (actualSeqLengthsKvOptional != nullptr && actualSeqLengthsKvTensor == nullptr) ||
125	        (actualSharedPrefixLenOptional != nullptr && actualSharedPrefixLenTensor == nullptr) ||
126	        (qStartIdxOptional != nullptr && qStartIdxTensor == nullptr) ||
127	        (kvStartIdxOptional != nullptr && kvStartIdxTensor == nullptr)) {
128	        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "FusedInferAttentionScore: convert IntArray to Tensor failed.");
129	        return {nullptr, nullptr};
130	    }
131	
132	    auto attentionOutOut = executor->AllocTensor(attentionOut->GetDataType(), Format::FORMAT_ND, Format::FORMAT_ND);
133	    if (attentionOutOut == nullptr) {
134	        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "FusedInferAttentionScore: alloc attentionOutOut failed.");
135	        return {nullptr, nullptr};
136	    }
137	    auto softmaxLseOut = executor->AllocTensor(softmaxLse->GetDataType(), Format::FORMAT_ND, Format::FORMAT_ND);
138	    if (softmaxLseOut == nullptr) {
139	        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "FusedInferAttentionScore: alloc softmaxLseOut failed.");
140	        return {nullptr, nullptr};
141	    }
142	    auto ret = INFER_SHAPE(FusedInferAttentionScore,
143	                           OP_INPUT(query, key, value, pseShiftOptional, attenMaskOptional, actualSeqLengthsTensor,
144	                                    actualSeqLengthsKvTensor, deqScale1Optional, quantScale1Optional, deqScale2Optional,
145	                                    quantScale2Optional, quantOffset2Optional, antiquantScaleOptional, antiquantOffsetOptional,
146	                                    blockTableOptional, queryPaddingSizeOptional, kvPaddingSizeOptional, keyAntiquantScaleOptional,
147	                                    keyAntiquantOffsetOptional, valueAntiquantScaleOptional, valueAntiquantOffsetOptional,
148	                                    keySharedPrefixOptional, valueSharedPrefixOptional, actualSharedPrefixLenTensor,
149	                                    queryRopeOptional, keyRopeOptional, keyRopeAntiquantScaleOptional, dequantScaleQueryOptional,
150	                                    learnableSinkOptional, qStartIdxTensor, kvStartIdxTensor),
151	                           OP_OUTPUT(attentionOutOut, softmaxLseOut),
