153	                                   sparseMode, innerPrecise, blockSize, antiquantMode, softmaxLseFlag, keyAntiquantMode,
154	                                   valueAntiquantMode, queryQuantMode, pseType, outDtype));
155	    if (ret != ACLNN_SUCCESS) {
156	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "FusedInferAttentionScore InferShape failed.");
157	        return {nullptr, nullptr};
158	    }
159	
160	    ret = ADD_TO_LAUNCHER_LIST_AICORE(FusedInferAttentionScore,
161	                                      OP_INPUT(query, key, value, pseShiftOptional, attenMaskOptional, actualSeqLengthsTensor,
