166	                                               keySharedPrefixOptional, valueSharedPrefixOptional, actualSharedPrefixLenTensor,
167	                                               queryRopeOptional, keyRopeOptional, keyRopeAntiquantScaleOptional, dequantScaleQueryOptional,
168	                                               learnableSinkOptional, qStartIdxTensor, kvStartIdxTensor),
169	                                      OP_OUTPUT(attentionOutOut, softmaxLseOut),
170	                                      OP_ATTR(numHeads, static_cast<float>(scaleValue), preTokens, nextTokens, inputLayout, numKeyValueHeads,
171	                                              sparseMode, innerPrecise, blockSize, antiquantMode, softmaxLseFlag, keyAntiquantMode,
172	                                              valueAntiquantMode, queryQuantMode, pseType, outDtype));
173	    if (ret != ACLNN_SUCCESS) {
174	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "FusedInferAttentionScore LaunchAicore failed.");
175	        return {nullptr, nullptr};
176	    }
177	
178	    return {attentionOutOut, softmaxLseOut};
179	}
