35	void TensorPreProcess(const aclTensorList *&tensorListKey, const aclTensorList *&tensorListValue)
36	{
37	    if (tensorListKey == nullptr) {
38	        OP_LOGD("TensorListKey is nullptr,TensorPreProcess exit.");
39	        return;
40	    }
41	    if (tensorListValue == nullptr) {
42	        OP_LOGD("tensorListValue is nullptr,TensorPreProcess exit.");
43	        return;
44	    }
45	    if ((*tensorListKey)[0]->GetDataType() != DataType::DT_INT32) {
46	        OP_LOGD("The conversion of kv's from OriginalShape is completed.");
47	        return;
48	    }
49	    if ((*tensorListValue)[0]->GetDataType() != DataType::DT_INT32) {
50	        OP_LOGD("The conversion of kv's from OriginalShape is completed.");
51	        return;
52	    }
53	    auto tempKey = const_cast<aclTensorList *>(tensorListKey);
54	    for (uint64_t i = 0; i < tempKey->Size(); i++) {
55	        if ((*tempKey)[i] != nullptr) {
56	            op::Shape viewShape = (*tempKey)[i]->GetViewShape();
57	            auto viewShapeDim = viewShape.GetDimNum();
58	            if (viewShapeDim >= 1) {
59	                viewShape[viewShapeDim - 1] = viewShape[viewShapeDim - 1] * INT4_NUMS_IN_INT32;
60	            }
61	            (*tempKey)[i]->SetViewShape(viewShape);
62	            (*tempKey)[i]->SetDataType(DataType::DT_INT4);
63	        }
64	    }
65	
66	    auto tempValue = const_cast<aclTensorList *>(tensorListValue);
67	    for (uint64_t i = 0; i < tempValue->Size(); i++) {
68	        if ((*tempValue)[i] != nullptr) {
69	            op::Shape viewShape = (*tempValue)[i]->GetViewShape();
70	            auto viewShapeDim = viewShape.GetDimNum();
71	            if (viewShapeDim >= 1) {
72	                viewShape[viewShapeDim - 1] = viewShape[viewShapeDim - 1] * INT4_NUMS_IN_INT32;
73	            }
74	            (*tempValue)[i]->SetViewShape(viewShape);
75	            (*tempValue)[i]->SetDataType(DataType::DT_INT4);
76	        }
77	    }
78	
79	    OP_LOGD("The conversion of kv from int32 to int4 is completed.");
80	}
