159	bool IsFAIRoutingCandidate(
160	    const aclTensor *query, const aclTensorList *key, const aclTensorList *value,
161	    const aclTensor *attenMaskOptional, const aclTensor *blockTableOptional,
162	    const aclTensor *queryRopeOptional, const aclTensor *keyRopeOptional,
163	    const aclTensor *learnableSinkOptional,
164	    const char *inputLayout, int64_t numHeads, int64_t numKeyValueHeads,
165	    int64_t sparseMode, int64_t innerPrecise)
166	{
167	    if (query == nullptr || key == nullptr || value == nullptr || key->Size() == 0 || value->Size() == 0 ||
168	        (*key)[0] == nullptr || (*value)[0] == nullptr || inputLayout == nullptr) {
169	        return false;
170	    }
171	
172	    constexpr int64_t MAX_HEAD_DIM = 256;
173	    constexpr int64_t MAX_BLOCK_SIZE = 512;
174	    constexpr int64_t BLOCK_SIZE_ALIGNMENT = 16;
175	    constexpr int64_t NZ_INNER_BLOCK = 16;
176	    constexpr int64_t UNSUPPORTED_SINK_HEAD_DIM = 64;
177	
178	    const std::string inputLayoutStr(inputLayout);
179	    const auto queryDtype = query->GetDataType();
180	    const auto queryShape = query->GetViewShape();
181	    const auto keyShape = (*key)[0]->GetViewShape();
182	    const auto valueShape = (*value)[0]->GetViewShape();
183	    if (queryShape.GetDimNum() <= 2) {
184	        return false;
185	    }
186	    const int64_t queryHeadDim = queryShape.GetDim(2);
187	
188	    bool learnableSinkSupported = true;
189	    if (learnableSinkOptional != nullptr && inputLayoutStr == "TND" &&
190	        queryHeadDim == UNSUPPORTED_SINK_HEAD_DIM &&
191	        learnableSinkOptional->GetDataType() == DataType::DT_BF16) {
192	        learnableSinkSupported = false;
193	    }
194	    const bool isRopeSplitMla = queryRopeOptional != nullptr && keyRopeOptional != nullptr;
195	    const bool sparseModeSupported = sparseMode == 0 || sparseMode == 3 || sparseMode == 4;
196	    const bool isMha = numKeyValueHeads == 0 || numHeads == numKeyValueHeads;
197	    const bool mhaConditions = isMha && !(queryDtype == DataType::DT_BF16 && innerPrecise == 1) &&
198	                               !(sparseMode == 0 && attenMaskOptional != nullptr);
199	    const bool nonMhaConditions = !isMha && innerPrecise == 0;
200	    if (inputLayoutStr != "TND" || !learnableSinkSupported || isRopeSplitMla || !sparseModeSupported ||
201	        (!mhaConditions && !nonMhaConditions)) {
202	        return false;
203	    }
204	
205	    if (blockTableOptional == nullptr) {
206	        if (keyShape.GetDimNum() <= 2 || valueShape.GetDimNum() <= 2) {
207	            return false;
208	        }
209	        const int64_t keyHeadDim = keyShape.GetDim(2);
210	        const int64_t valueHeadDim = valueShape.GetDim(2);
211	        return queryHeadDim <= MAX_HEAD_DIM && keyHeadDim <= MAX_HEAD_DIM && valueHeadDim <= MAX_HEAD_DIM &&
212	               queryHeadDim == keyHeadDim && queryHeadDim == valueHeadDim;
213	    }
214	    if (keyShape.GetDimNum() == 3) {
215	        if (valueShape.GetDimNum() <= 2 || numKeyValueHeads == 0) {
216	            return false;
217	        }
218	        const int64_t blockSize = keyShape.GetDim(1);
219	        const int64_t keyHeadDim = keyShape.GetDim(2) / numKeyValueHeads;
220	        const int64_t valueHeadDim = valueShape.GetDim(2) / numKeyValueHeads;
221	        return queryHeadDim <= MAX_HEAD_DIM && keyHeadDim <= MAX_HEAD_DIM && valueHeadDim <= MAX_HEAD_DIM &&
222	               queryHeadDim == keyHeadDim && queryHeadDim == valueHeadDim &&
223	               blockSize % BLOCK_SIZE_ALIGNMENT == 0 && blockSize <= MAX_BLOCK_SIZE;
224	    }
225	    if (keyShape.GetDimNum() == 5) {
226	        if (valueShape.GetDimNum() <= 3) {
227	            return false;
228	        }
229	        const int64_t blockSize = keyShape.GetDim(3);
230	        const int64_t keyHeadDim = keyShape.GetDim(2) * NZ_INNER_BLOCK;
231	        const int64_t valueHeadDim = valueShape.GetDim(2) * NZ_INNER_BLOCK;
232	        const bool headDimSupported = queryHeadDim <= MAX_HEAD_DIM && keyHeadDim <= MAX_HEAD_DIM &&
233	                                      valueHeadDim <= MAX_HEAD_DIM && queryHeadDim == keyHeadDim && queryHeadDim == valueHeadDim &&
234	                                      queryHeadDim != 64 && queryHeadDim != 128;
235	        return headDimSupported && blockSize % BLOCK_SIZE_ALIGNMENT == 0 && blockSize <= MAX_BLOCK_SIZE;
236	    }
237	    return false;
238	}
