240	bool GetAclTensorViewStrides(const aclTensor *tensor, int64_t *&stridesValue, uint64_t &stridesNum)
241	{
242	    stridesValue = nullptr;
243	    stridesNum = 0;
244	    auto retView = aclGetViewStrides(tensor, &stridesValue, &stridesNum);
245	    if (retView != ACL_SUCCESS || stridesValue == nullptr) {
246	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "aclGetViewStrides failed.");
247	        delete[] stridesValue;
248	        stridesValue = nullptr;
249	        stridesNum = 0;
250	        return false;
251	    }
252	    return true;
253	}
