255	bool IsFirstAxisOnlyNonContiguous(const aclTensor *tensor, const char *name)
256	{
257	    if (tensor == nullptr) {
258	        return true;
259	    }
260	    if (IsContiguous(tensor)) {
261	        return true;
262	    }
263	
264	    auto viewShape = tensor->GetViewShape();
265	    int64_t dimNum = viewShape.GetDimNum();
266	    if (dimNum <= 1) {
267	        OP_LOGW("%s is non-contiguous with dim num[%ld] <= 1, it will be forced to be contiguous.", name, dimNum);
268	        return false;
269	    }
270	
271	    int64_t *viewStrides = nullptr;
272	    uint64_t stridesNum = 0;
273	    if (!GetAclTensorViewStrides(tensor, viewStrides, stridesNum)) {
274	        OP_LOGW("Failed to get view strides for %s, it will be forced to be contiguous.", name);
275	        return false;
276	    }
277	    if (stridesNum < static_cast<uint64_t>(dimNum)) {
278	        OP_LOGW("%s view strides num[%lu] is less than view shape dim num[%ld], it will be forced to be contiguous.",
279	                name, stridesNum, dimNum);
280	        delete[] viewStrides;
281	        return false;
282	    }
283	
284	    bool isFirstAxisOnlyNonContiguous = true;
285	    int64_t expectedStride = 1;
286	    for (int64_t dim = dimNum - 1; dim >= 1; --dim) {
287	        if (viewShape.GetDim(dim) != 1 && viewStrides[dim] != expectedStride) {
288	            OP_LOGW("%s is non-contiguous at axis[%ld] (0-based): actual stride[%ld], expected stride[%ld], "
289	                    "shape[%s]. It will be forced to be contiguous.",
290	                    name, dim, viewStrides[dim], expectedStride, op::ToString(viewShape).GetString());
291	            isFirstAxisOnlyNonContiguous = false;
292	            break;
293	        }
294	        expectedStride *= viewShape.GetDim(dim);
295	    }
296	
297	    delete[] viewStrides;
298	    return isFirstAxisOnlyNonContiguous;
299	}
