312	aclnnStatus MakeTensorListContiguous(const aclTensorList *&tensorList, const char *name, aclOpExecutor *executor)
313	{
314	    if (tensorList == nullptr) {
315	        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "%s tensorList is nullptr.", name);
316	        return ACLNN_ERR_PARAM_NULLPTR;
317	    }
318	
319	    std::vector<const aclTensor *> tensors;
320	    tensors.reserve(tensorList->Size());
321	    for (uint64_t i = 0; i < tensorList->Size(); ++i) {
322	        auto tensor = (*tensorList)[i];
323	        if (tensor == nullptr) {
324	            tensors.emplace_back(nullptr);
325	            continue;
326	        }
327	        auto contiguousTensor = l0op::Contiguous(tensor, executor);
328	        if (contiguousTensor == nullptr) {
329	            OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try make %s[%lu] contiguous failed.", name, i);
330	            return ACLNN_ERR_INNER_NULLPTR;
331	        }
332	        tensors.emplace_back(contiguousTensor);
333	    }
334	
335	    auto contiguousList = executor->AllocTensorList(tensors.data(), tensors.size());
336	    if (contiguousList == nullptr) {
337	        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try alloc contiguous %s tensorList failed.", name);
338	        return ACLNN_ERR_INNER_NULLPTR;
339	    }
340	    tensorList = contiguousList;
341	
342	    for (uint64_t i = 0; i < tensorList->Size(); ++i) {
343	        auto tensor = (*tensorList)[i];
344	        if (tensor != nullptr) {
345	            SetTensorFormatToND(tensor);
346	        }
347	    }
348	
349	    return ACLNN_SUCCESS;
350	}
