367	aclnnStatus NormalizeFAICacheTensorList(const aclTensorList *&tensorList, const char *name, aclOpExecutor *executor)
368	{
369	    if (tensorList == nullptr) {
370	        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "%s tensorList is nullptr.", name);
371	        return ACLNN_ERR_PARAM_NULLPTR;
372	    }
373	
374	    std::vector<const aclTensor *> tensors;
375	    tensors.reserve(tensorList->Size());
376	    for (uint64_t i = 0; i < tensorList->Size(); ++i) {
377	        auto tensor = (*tensorList)[i];
378	        if (tensor == nullptr) {
379	            tensors.emplace_back(nullptr);
380	            continue;
381	        }
382	
383	        const aclTensor *normalizedTensor = nullptr;
384	        std::string itemName = std::string(name) + "[" + std::to_string(i) + "]";
385	        if (IsContiguous(tensor)) {
386	            normalizedTensor = l0op::Contiguous(tensor, executor);
387	            if (normalizedTensor == nullptr) {
388	                OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try normalize contiguous %s failed.", itemName.c_str());
389	                return ACLNN_ERR_INNER_NULLPTR;
390	            }
391	        } else if (IsFirstAxisOnlyNonContiguous(tensor, itemName.c_str())) {
392	            normalizedTensor = executor->CreateView(tensor, tensor->GetViewShape(), tensor->GetStorageShape(),
393	                                                    tensor->GetViewStrides(), tensor->GetViewOffset());
394	            if (normalizedTensor == nullptr) {
395	                OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try create view for %s failed.", itemName.c_str());
396	                return ACLNN_ERR_INNER_NULLPTR;
397	            }
398	            const_cast<aclTensor *>(normalizedTensor)->SetStorageShape(tensor->GetViewShape());
399	        } else {
400	            normalizedTensor = l0op::Contiguous(tensor, executor);
401	            if (normalizedTensor == nullptr) {
402	                OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try make %s contiguous failed.", itemName.c_str());
403	                return ACLNN_ERR_INNER_NULLPTR;
404	            }
405	        }
406	        SetTensorFormatToND(normalizedTensor);
407	        tensors.emplace_back(normalizedTensor);
408	    }
409	
410	    auto normalizedList = executor->AllocTensorList(tensors.data(), tensors.size());
411	    if (normalizedList == nullptr) {
412	        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try alloc normalized %s tensorList failed.", name);
413	        return ACLNN_ERR_INNER_NULLPTR;
414	    }
415	    tensorList = normalizedList;
416	    return ACLNN_SUCCESS;
417	}
