419	aclnnStatus ProcessKVForL0Input(const aclTensorList *&key, const aclTensorList *&value,
420	                                const aclTensor *blockTableOptional, bool isFAIRoutingCandidate,
421	                                aclOpExecutor *executor)
422	{
423	    if (executor == nullptr) {
424	        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "executor is nullptr.");
425	        return ACLNN_ERR_PARAM_NULLPTR;
426	    }
427	    if (key == nullptr || value == nullptr) {
428	        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "key or value tensorList is nullptr.");
429	        return ACLNN_ERR_PARAM_NULLPTR;
430	    }
431	    if (key->Size() != value->Size()) {
432	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "key tensorList size[%lu] should be equal to value tensorList size[%lu].",
433	                key->Size(), value->Size());
434	        return ACLNN_ERR_PARAM_INVALID;
435	    }
436	
437	    const bool isCacheScene = IsCacheScene(blockTableOptional);
438	    const bool supportTensorV2 = NnopbaseSupportTensorV2 != nullptr;
439	    if (supportTensorV2 && isFAIRoutingCandidate && isCacheScene) {
440	        CHECK_RET(NormalizeFAICacheTensorList(key, "key", executor) == ACLNN_SUCCESS, ACLNN_ERR_INNER_NULLPTR);
441	        CHECK_RET(NormalizeFAICacheTensorList(value, "value", executor) == ACLNN_SUCCESS, ACLNN_ERR_INNER_NULLPTR);
442	        return ACLNN_SUCCESS;
443	    }
444	
445	    if (!supportTensorV2) {
446	        OP_LOGW("Current opbase does not support TensorV2, make key and value contiguous.");
447	    }
448	
449	    CHECK_RET(MakeTensorListContiguous(key, "key", executor) == ACLNN_SUCCESS, ACLNN_ERR_INNER_NULLPTR);
450	    CHECK_RET(MakeTensorListContiguous(value, "value", executor) == ACLNN_SUCCESS, ACLNN_ERR_INNER_NULLPTR);
451	    return ACLNN_SUCCESS;
452	}
