    void *workspace, uint64_t workspaceSize, aclOpExecutor *executor, const aclrtStream stream)
{
    L2_DFX_PHASE_2(InnerFusedInferAttentionScore);
    auto ret = CommonOpExecutorRun(workspace, workspaceSize, executor, stream);
    return ret;
}

