    }
    if (keyRopeOptional != nullptr && !IsContiguous(keyRopeOptional)) {
        return ACLNN_ERR_INNER_TILING_ERROR;
    }
    if ((keyAntiquantScaleOptional != nullptr && !IsContiguous(keyAntiquantScaleOptional)) ||
